// Один воркфлоу — три входа. Куда пошла работа, определяем здесь:
//   queue        — тик расписания (у него нет ни body, ни headers);
//   create_jobs  — вебхук publishing-create-jobs (видео уже принято);
//   video_ready  — вебхук publishing-video-ready (новое видео).
// Заодно собираем тело для publish-intake и проверяем заявку: невалидная
// возвращает причину, а не generic-500.
const src = $input.first().json;
const url = String(src.webhookUrl || '');
const b = src.body || {};
const isWebhook = Boolean(src.body || src.headers);

if (!isWebhook) return [{ json: { route: 'queue', valid: true } }];

// Вебхук открыт всему интернету, а дальше по цепочке лежит ключ автоматизации
// Supabase: без этой проверки кто угодно ставит публикации в живые аккаунты.
// Заголовок x-publish-key должен совпадать с webhook_key из «Настроек».
const headers = src.headers || {};
const given = headers['x-publish-key'] || headers['X-Publish-Key'] || '';
if (!src.webhook_key || given !== src.webhook_key) {
  return [{ json: { route: 'denied', valid: false, error: 'unauthorized: нужен заголовок x-publish-key' } }];
}

const route = url.includes('publishing-create-jobs') || (b.video_id && !b.file_url)
  ? 'create_jobs'
  : 'video_ready';

if (route === 'create_jobs') {
  if (!b.video_id) return [{ json: { route, valid: false, error: 'video_id обязателен' } }];
  const t = b.target || {};
  return [{ json: { route, valid: true, payload: {
    action: 'create_jobs',
    video_id: b.video_id,
    target: {
      group_id: t.group_id ?? undefined,
      account_ids: Array.isArray(t.account_ids) ? t.account_ids : undefined,
      platforms: Array.isArray(t.platforms) ? t.platforms : undefined,
      mode: t.mode ?? 'drip',
      per_hour: t.per_hour ?? 10,
      start_at: t.start_at ?? undefined,
    },
  } } }];
}

const missing = ['project_id', 'file_url'].filter((k) => !b[k]);
if (missing.length) return [{ json: { route, valid: false, error: 'не хватает полей: ' + missing.join(', ') } }];

return [{ json: { route, valid: true, payload: {
  action: 'video_ready',
  project_id: b.project_id,
  file_url: b.file_url,
  thumbnail_url: b.thumbnail_url ?? null,
  title: b.title ?? null,
  base_caption: b.base_caption ?? b.caption ?? null,
  caption_variants: Array.isArray(b.caption_variants) ? b.caption_variants : [],
  hashtags: Array.isArray(b.hashtags) ? b.hashtags : [],
  duration_sec: b.duration_sec ?? null,
  width: b.width ?? null,
  height: b.height ?? null,
  source: b.source ?? 'n8n',
  source_ref: b.source_ref ?? null,
  // По умолчанию — все активные Instagram-аккаунты проекта, 10 постов в час.
  target: b.target || { platforms: ['instagram'], mode: 'drip', per_hour: 10 },
} } }];

// Сводим разбор очереди и монитор аварийных аккаунтов.
// Молчим, когда сказать нечего, — иначе чат забьётся пустыми тиками.
const w = $('publish-worker').first().json.body ?? $('publish-worker').first().json;
const m = $input.first().json.body ?? $input.first().json;

const lines = [];
if (w.published) lines.push(`✅ Опубликовано: ${w.published}`);
if (w.failed) lines.push(`❌ Не удалось: ${w.failed}`);
if (w.manual_review) lines.push(`🔍 На ручной разбор: ${w.manual_review}`);
// Отказ шлюза приходит как message, отказ функции — как error: ловим оба.
const werr = w.error ?? w.message;
const merr = m.error ?? m.message;
if (werr) lines.push(`⚠️ Воркер: ${werr}`);
if (m.disabled) lines.push(`🛑 Отключено аккаунтов по серии ошибок: ${m.disabled}`);
if (m.manual_review) lines.push(`📋 Всего заданий на разборе: ${m.manual_review}`);
if (merr) lines.push(`⚠️ Монитор: ${merr}`);

return [{ json: {
  ok: !werr && !merr,
  silent: lines.length === 0,
  claimed: w.claimed ?? 0,
  published: w.published ?? 0,
  failed: w.failed ?? 0,
  text: lines.length ? `📹 Автопостинг\n${lines.join('\n')}` : '',
} }];

// Ответ publish-intake → человеку и в вебхук.
const r = $input.first().json;
const body = r.body ?? r;
const ok = (r.statusCode ?? 200) < 300 && !body.error;
// Ошибку достаём и из message, и из кода ответа — иначе «неизвестная ошибка».
const err = body.error ?? body.message ?? (ok ? null : `HTTP ${r.statusCode}`);
const accounts = body.accounts ?? [];
const listed = accounts.length
  ? `\n• ${accounts.map((a) => `${a.account_name} — ${new Date(a.scheduled_at).toLocaleString('ru-RU')}`).join('\n• ')}`
  : '';
return [{ json: {
  ok,
  silent: ok && !accounts.length,
  video_id: body.video_id ?? null,
  created: body.created ?? 0,
  skipped: body.skipped ?? 0,
  error: err,
  text: ok
    ? `🎬 Видео в публикации\nЗаданий создано: ${body.created ?? 0}` +
      (body.skipped ? `\nПропущено (уже стояли): ${body.skipped}` : '') + listed
    : `❌ Заявка не принята: ${err}`,
} }];
